def largest_altitude(gain):
    n = len(gain)
    highest = 0                                                # the starting altitude is always a candidate
    for i in range(1, n + 1):
        altitude = sum(gain[:i])                                   # resums from the very start every single time
        highest = max(highest, altitude)
    return highest


if __name__ == "__main__":
    print(largest_altitude([-5, 1, 5, 0, -7]))

