import java.util.*;

public class Main {
    int largestAltitude(int[] gain) {
        int n = gain.length;
        int highest = 0;                                                // the starting altitude is always a candidate
        for (int i = 1; i <= n; i++) {
            int altitude = 0;
            for (int j = 0; j < i; j++) altitude += gain[j];                // resums from the very start every single time
            highest = Math.max(highest, altitude);
        }
        return highest;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.largestAltitude(new int[]{-5, 1, 5, 0, -7}));
    }
}

